import pathlib,json,hashlib,tarfile,tempfile,subprocess,datetime
ROOT=pathlib.Path('/home/administrator/projects/hexalith/folders');E=ROOT/'_bmad-output/implementation-artifacts/evidence';RP=E/'story-1-17-owner-intake-2026-10-25.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def require(ok,msg):
 if not ok:raise RuntimeError(msg)
r=json.loads(RP.read_text());out={'recordId':'STORY-1-17-OWNER-INTAKE-PARENT-VERIFICATION-2026-10-25','recordedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'receiptSha256':sha(RP),'checks':[]}
for k in ['archive','memberManifest','handoff','decisions','readableDecisions','verification']:
 p=E/r[k]['path'];require(sha(p)==r[k]['sha256'],k+' digest');out[k+'Sha256']=sha(p)
w=pathlib.Path(tempfile.mkdtemp(prefix='story117-owner-parent-final-'))
with tarfile.open(E/r['archive']['path']) as t:t.extractall(w,filter='data')
for flags in [[],['-O']]:
 for script,args in [('replay.py',['--receipt',str(RP)]),('test_replay.py',[])]:
  cmd=['python3','-B',*flags,str(w/script),*args];start=datetime.datetime.now(datetime.timezone.utc).isoformat();p=subprocess.run(cmd,cwd=w,capture_output=True,text=True);row={'command':cmd,'cwd':str(w),'startedAtUtc':start,'completedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exitCode':p.returncode,'stdout':p.stdout,'stderr':p.stderr,'stdoutSha256':hashlib.sha256(p.stdout.encode()).hexdigest(),'stderrSha256':hashlib.sha256(p.stderr.encode()).hexdigest()};out['checks'].append(row);print(script,flags,p.returncode,p.stdout.strip(),p.stderr[-300:],flush=True);require(p.returncode==0,'Final '+script+' failed')
after=json.loads((w/'after.json').read_text())['repositories'];pres=[]
for rel,a in after.items():
 p=ROOT/rel;head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=p).decode().strip();idx=hashlib.sha256(subprocess.check_output(['git','ls-files','--stage'],cwd=p)).hexdigest();bad=[f for f,h in a['files'].items() if not (p/f).is_file() or sha(p/f)!=h];links=[s for s in subprocess.check_output(['git','ls-files','--stage'],cwd=p).decode().splitlines() if s.startswith('160000')];nested={x.split('\t',1)[1]:(p/x.split('\t',1)[1]/'.git').exists() for x in links} if rel!='.' else {};require(head==a['revision'] and idx==a['indexEntriesSha256'] and links==a['gitlinks'] and nested==a['nestedGitMarkers'] and not bad,rel+' source drift');pres.append({'repository':rel,'revision':head,'indexEntriesSha256':idx,'trackedFilesCompared':len(a['files']),'changedTrackedFiles':bad,'gitlinksMatch':True,'nestedMarkersMatch':True})
out['sourcePreservation']={'checkedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'capsuleSnapshot':'after.json','capsuleSnapshotSha256':sha(w/'after.json'),'repositories':pres,'allPreserved':True,'newSpecLifecycleEdits':'Only this newly created continuation spec was marked in-review/completed; it was not a pre-existing user file. Parent story/tracker remain byte-identical.'}
out['review']={'layers':['blind','edge cases','verification gaps'],'findings':16,'distinctPatchGroups':11,'disposition':'All reproduced findings corrected through evidence-only comparisons and focused controls; no application or validation gate weakened.'}
out['scope']='Local evidence verified; ordinary mapping, adoption, current tuple, publication and hosted acceptance remain HOLD. No application build, audit or prior suite rerun during review remediation.'
for k in ['operationalControl','stagingChecks']:out[k]=r[k]
out['parentStatus']='in-progress';out['trackerStatus']='backlog';out['verificationDriver']={'command':['python3','-B',str(pathlib.Path(__file__).resolve())],'source':pathlib.Path(__file__).read_text()}
path=E/'story-1-17-owner-intake-2026-10-25.parent-verification.json';path.write_text(json.dumps(out,indent=2)+'\n');print('parentVerification',path,'extraction',w,flush=True);pathlib.Path('/tmp/story117-owner-intake-20261025-4w9dr812/final-extraction-path').write_text(str(w))

